<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, type AIConfig } from '../lib/api'
import { user, authOpen, notify, message, changeIdentity } from '../lib/state'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
const config=ref<AIConfig>(),baseUrl=ref(''),model=ref(''),apiKey=ref(''),error=ref(''),busy=ref(false),loading=ref(true),logoutOpen=ref(false)
async function load(){loading.value=true;error.value='';try{config.value=await api.config();baseUrl.value=config.value.baseUrl;model.value=config.value.model}catch(e){error.value=message(e)}finally{loading.value=false}}
async function save(){if(!config.value)return;error.value='';busy.value=true;try{if(new URL(baseUrl.value).host!==new URL(config.value.baseUrl).host&&!apiKey.value){error.value='更换服务商地址时，请填写对应的新密钥';return}config.value=await api.saveConfig({baseUrl:baseUrl.value,model:model.value,apiKey:apiKey.value});apiKey.value='';notify('模型配置已保存')}catch(e){error.value=message(e)}finally{busy.value=false}}
async function logout(){busy.value=true;try{if(!await changeIdentity(()=>api.logout()))return;logoutOpen.value=false;notify('已退出，当前为新的访客空间')}catch(e){notify(message(e))}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="page-container settings-page"><header class="page-heading"><div><h1>模型与账户</h1><p>连接自己的模型，为学习资料生成辅助练习</p></div></header><div class="settings-grid"><section class="surface"><div class="section-head"><h2><Icon name="ai"/>模型连接</h2><span class="badge" :class="{configured:config?.configured}">{{config?.configured?'已配置':'未配置'}}</span></div><div v-if="loading" class="loading">正在读取配置…</div><form v-else-if="config" class="form-stack" @submit.prevent="save"><label>服务地址<input v-model="baseUrl" type="url" required placeholder="兼容 Chat Completions 的 HTTPS 地址"/></label><p class="field-hint">支持服务端允许的模型提供商 HTTPS 地址，更换服务商需填写新密钥。</p><label>模型名称<input v-model="model" required placeholder="填写服务商提供的模型名称"/></label><label>API 密钥<input v-model="apiKey" type="password" autocomplete="new-password" :placeholder="config.configured?'已配置，留空保留现有密钥':'填写模型服务商提供的密钥'"/></label><p class="inline-note"><Icon name="lock"/>密钥仅保存在服务端当前进程的用户配置中，不回显到页面。服务器重启后需要重新配置。</p><button class="button primary" :disabled="busy">{{busy?'正在保存…':'保存模型设置'}}</button></form><p v-if="error" class="error" role="alert">{{error}}<button v-if="!config" class="text-button" @click="load">重试</button></p></section><aside><section class="surface account-card"><span class="avatar large-avatar"><Icon name="user"/></span><h2>{{user?.name}}</h2><p class="muted">{{user?.email || '正在使用独立的访客空间'}}</p><p class="small muted">{{user?.email?'题集和练习记录与你的账户关联':'当前浏览器可以保留访客会话。绑定账户后，可登录找回学习内容。'}}</p><button v-if="!user?.email" class="button" @click="authOpen=true">创建账户或登录</button><button v-else class="button" @click="logoutOpen=true"><Icon name="logout"/>退出登录</button></section><section class="editor-tip"><h3>让 AI 辅助思考</h3><p>在题集编辑器中粘贴学习资料。生成结果需要你检查，只有保存后才会成为题集内容。</p><RouterLink to="/sets/new" class="text-button">创建题集<Icon name="right"/></RouterLink></section></aside></div><Modal :open="logoutOpen" title="退出当前账户？" @close="logoutOpen=false"><p>退出后会进入新的访客空间。重新登录即可查看当前账户的学习内容。</p><div class="modal-actions"><button class="button" @click="logoutOpen=false">取消</button><button class="button primary" :disabled="busy" @click="logout">退出登录</button></div></Modal></div></template>
